/* Forced offline PDF downloads - CURRENT site version. */
(function(){
  const PDFS={"MA-142":"","SK-219":"","TG-441":"","LN-728":"","FA-955":"","DEMO-104":"","DEMO-102":"","DEMO-103":""};
  function decodeBase64(b64){const raw=atob(b64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return bytes;}
  window.downloadCvFile=function(id){
    const w=(typeof workers!=="undefined")?workers.find(x=>x.id===id):null;if(!w)return;
    const code=String(w.code||"cv"),b64=PDFS[code];
    if(!b64){if(typeof toast==="function")toast("ملف السيرة غير متوفر للتنزيل.");return;}
    try{const bytes=decodeBase64(b64),blob=new Blob([bytes],{type:"application/pdf"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=code+".pdf";a.style.display="none";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);document.documentElement.dataset.lastDownload=code+".pdf";}catch(e){console.error("CV download failed",e);if(typeof toast==="function")toast("تعذر تنزيل ملف السيرة.");}
  };
})();
